--- a/training/level-1/L1-005-case-convert/convertCase.mjs
+++ b/training/level-1/L1-005-case-convert/convertCase.mjs
@@ -0,0 +1,50 @@
+export function convertCase(input, mode) {
+  if (input === null || input === undefined) {
+    return '';
+  }
+  const str = String(input);
+  const modes = ['lower', 'upper', 'title', 'sentence', 'camel', 'pascal', 'snake', 'kebab'];
+  if (!modes.includes(mode)) {
+    throw new RangeError(`Unsupported mode: ${mode}`);
+  }
+
+  switch (mode) {
+    case 'lower':
+      return str.toLowerCase();
+    case 'upper':
+      return str.toUpperCase();
+    case 'title':
+      return str
+        .split(/(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])|(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])/)
+        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
+        .join(' ');
+    case 'sentence':
+      return str
+        .toLowerCase()
+        .split(/(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])|(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])/)
+        .map((word, index) => index === 0 ? word.charAt(0).toUpperCase() + word.slice(1) : word)
+        .join(' ');
+    case 'camel':
+      return str
+        .split(/(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])|(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])/)
+        .map((word, index) => index === 0 ? word.toLowerCase() : word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
+        .join('');
+    case 'pascal':
+      return str
+        .split(/(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])|(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])/)
+        .map(word => word.charAt(0).toUpperCase() + word.slice(1).toUpperCase())
+        .join('');
+    case 'snake':
+      return str
+        .split(/(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])|(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])/)
+        .map(word => word.toLowerCase())
+        .join('_');
+    case 'kebab':
+      return str
+        .split(/(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])|(?<=[^A-Za-z0-9])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[^A-Za-z0-9])/)
+        .map(word => word.toLowerCase())
+        .join('-');
+    default:
+      throw new RangeError(`Unsupported mode: ${mode}`);
+  }
+}

